<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require_admin($pdo);
$isExportRequest = $_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['export']);
$input = $isExportRequest ? $_POST : $_GET;
$filters=['q'=>trim((string)($input['q']??'')),'action'=>trim((string)($input['action']??'')),'entity'=>trim((string)($input['entity']??'')),'from'=>trim((string)($input['from']??'')),'to'=>trim((string)($input['to']??''))];
$where=[];$args=[];
if($filters['q']!==''){$where[]='(a.action LIKE ? OR a.entity_type LIKE ? OR CAST(a.entity_id AS CHAR) LIKE ? OR a.before_data LIKE ? OR a.after_data LIKE ?)';array_push($args,...array_fill(0,5,'%'.$filters['q'].'%'));}
if(preg_match('/^[a-z0-9_]{1,80}$/i',$filters['action'])){$where[]='a.action=?';$args[]=$filters['action'];}
if(preg_match('/^[a-z0-9_]{1,60}$/i',$filters['entity'])){$where[]='a.entity_type=?';$args[]=$filters['entity'];}
foreach(['from'=>'>=','to'=>'<='] as $key=>$op){if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$filters[$key])){$where[]='DATE(a.created_at)'.$op.'?';$args[]=$filters[$key];}}
$sql='SELECT a.*,COALESCE(NULLIF(CONCAT_WS(" ",i.first_name,i.last_name),""),CONCAT("User #",a.actor_user_id),"System/guest") actor_name FROM audit_logs a LEFT JOIN user_info i ON i.user_id=a.actor_user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.created_at DESC,a.audit_id DESC';
$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();
$format=$isExportRequest ? (string)$_POST['export'] : '';
if(in_array($format,['csv','json','xml','txt'],true)){
 if (!csrf_check($_POST['csrf'] ?? null) || !verify_account_password($pdo, (int)$_SESSION['user_id'], (string)($_POST['password'] ?? ''))) { http_response_code(403); exit('Export authentication failed. Return to the audit log and try again.'); }
 $base='audit-log-'.date('Ymd-His');header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="'.$base.'.'.$format.'"');
 if($format==='csv'){header('Content-Type: text/csv; charset=utf-8');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['ID','Timestamp','Actor','Actor ID','Action','Entity','Entity ID','Before','After']);foreach($rows as $r)fputcsv($out,[$r['audit_id'],$r['created_at'],$r['actor_name'],$r['actor_user_id'],$r['action'],$r['entity_type'],$r['entity_id'],$r['before_data'],$r['after_data']]);fclose($out);exit;}
 if($format==='json'){header('Content-Type: application/json; charset=utf-8');echo json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);exit;}
 if($format==='xml'){header('Content-Type: application/xml; charset=utf-8');echo "<?xml version=\"1.0\" encoding=\"UTF-8\"?><audit_logs>";foreach($rows as $r){echo '<entry>';foreach($r as $k=>$v)echo '<'.preg_replace('/[^a-z0-9_]/i','',$k).'>'.htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8').'</'.preg_replace('/[^a-z0-9_]/i','',$k).'>';echo '</entry>';}echo '</audit_logs>';exit;}
 header('Content-Type: text/plain; charset=utf-8');foreach($rows as $r)echo implode("\t",[$r['audit_id'],$r['created_at'],$r['actor_name'],$r['action'],$r['entity_type'].'#'.$r['entity_id'],$r['before_data'],$r['after_data']])."\n";exit;
}
$actions=$pdo->query('SELECT DISTINCT action FROM audit_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN);$entities=$pdo->query('SELECT DISTINCT entity_type FROM audit_logs ORDER BY entity_type')->fetchAll(PDO::FETCH_COLUMN);
$pageTitle='Audit log';require 'includes/header.php';
?>
<main class="container py-5"><div class="d-flex justify-content-between align-items-end mb-4"><div><p class="text-uppercase small fw-semibold text-secondary mb-1">Admin tool</p><h1>Audit log</h1><p class="text-secondary mb-0">Search recorded actions and export the filtered results.</p></div><div class="dropdown"><button class="btn btn-auth dropdown-toggle" data-bs-toggle="dropdown">Export</button><ul class="dropdown-menu dropdown-menu-end"><?php foreach(['csv'=>'CSV','json'=>'JSON','xml'=>'XML','txt'=>'Text'] as $ext=>$label):?><li><button class="dropdown-item" type="button" data-export-format="<?=e($ext)?>">Download <?=e($label)?></button></li><?php endforeach;?></ul></div></div>
<form method="get" class="form-panel mb-3" id="audit-filters"><div class="row g-2"><div class="col-md-4"><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($filters['q'])?>" placeholder="Actor, action, entity, values"></div><div class="col-md-2"><label class="form-label">Action</label><select class="form-select" name="action"><option value="">All actions</option><?php foreach($actions as $v):?><option value="<?=e($v)?>" <?=$filters['action']===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Entity</label><select class="form-select" name="entity"><option value="">All entities</option><?php foreach($entities as $v):?><option value="<?=e($v)?>" <?=$filters['entity']===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($filters['from'])?>"></div><div class="col-md-2"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($filters['to'])?>"></div></div><div class="mt-3 d-flex justify-content-end"><a class="btn btn-sm btn-outline-secondary" href="audit-log.php"><i class="bi bi-x-circle me-1" aria-hidden="true"></i>Clear filters</a></div></form>
<p class="text-secondary"><?=count($rows)?> matching record(s)</p><div class="table-responsive form-panel p-0"><table class="table table-sm align-middle mb-0"><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Entity</th><th>Changes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['actor_name'])?></td><td><?=e($r['action'])?></td><td><?=e($r['entity_type'])?> #<?=e((string)$r['entity_id'])?></td><td><button type="button" class="btn btn-sm btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#auditChange<?= (int)$r['audit_id'] ?>">View</button><div class="modal fade" id="auditChange<?= (int)$r['audit_id'] ?>" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5">Audit changes</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p><strong><?=e($r['action'])?></strong> · <?=e($r['entity_type'])?> #<?=e((string)$r['entity_id'])?></p><div class="row g-3"><div class="col-md-6"><h3 class="h6">Before</h3><pre class="bg-light p-3 rounded text-wrap"><?=e($r['before_data']??'—')?></pre></div><div class="col-md-6"><h3 class="h6">After</h3><pre class="bg-light p-3 rounded text-wrap"><?=e($r['after_data']??'—')?></pre></div></div></div></div></div></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center py-4">No audit records found.</td></tr><?php endif;?></tbody></table></div></main><script>
(()=>{const form=document.getElementById('audit-filters');if(!form)return;let timer;form.querySelectorAll('select,input[type="date"]').forEach(el=>el.addEventListener('change',()=>form.requestSubmit()));const search=form.querySelector('input[name="q"]');search?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>form.requestSubmit(),350);});})();
</script><?php require 'includes/footer.php'; ?>
